const worlds={earth:{name:'NOMAD TERRE',city:'VILLE CENTRALE',emoji:'🌍',desc:'Ville terrestre déjà habitée : quartiers, campagne, montagne et littoral.',bg:'terre'},sea:{name:'NOMAD MER',city:'VILLE FLOTTANTE',emoji:'🌊',desc:'Village marin déjà installé : plateformes, serres, docks et océan.',bg:'mer'},mountain:{name:'NOMAD MONTAGNE',city:'VILLE DES HAUTEURS',emoji:'⛰️',desc:'Ville de montagne déjà construite : relief, ateliers et habitats.',bg:'montagne'},moon:{name:'NOMAD LUNE',city:'VILLE LUNAIRE',emoji:'🌙',desc:'Ville lunaire déjà habitée : habitats, serres, docks et exploration.',bg:'lune'},mars:{name:'NOMAD MARS',city:'VILLE MARTIENNE',emoji:'🔴',desc:'Ville martienne déjà habitée : serres, ressources et exploration.',bg:'mars'},space:{name:'NOMAD ESPACE',city:'VILLE ORBITALE',emoji:'🛰️',desc:'Ville orbitale déjà habitée : stations, docks et habitats.',bg:'espace'}};let s=JSON.parse(localStorage.getItem('nomadSims'))||{world:'earth',name:'Nomad',bot:'JERVIS',money:1000,home:null,x:48,y:58,time:8,mood:'Bien'};const $=x=>document.getElementById(x);function save(){localStorage.setItem('nomadSims',JSON.stringify(s))}function msg(t){$('message').textContent=t}function render(){let w=worlds[s.world];$('worldName').textContent=w.name;$('cityTitle').textContent=w.name+' · '+w.city;$('name').textContent=s.name;$('botName').textContent=s.bot;$('money').textContent=s.money.toLocaleString('fr-FR');$('clock').textContent=String(Math.floor(s.time)%24).padStart(2,'0')+':'+(s.time%1?30:'00');$('mood').textContent=s.mood;$('homeStatus').textContent=s.home?'Vous êtes chez vous 🏡':'Vous êtes visiteur';$('homeText').textContent=s.home?'Votre habitat est greffé à la ville. Vous pouvez maintenant vivre comme les autres habitants.':'La ville vous accueille. Choisissez un terrain libre quand vous êtes prêt.';$('claim').disabled=!window.selectedPlot||!!s.home;$('player').style.left=s.x+'%';$('player').style.top=s.y+'%';$('bot').style.left=(s.x+4)+'%';$('bot').style.top=(s.y+5)+'%';document.querySelectorAll('.plot').forEach(p=>{p.classList.toggle('selected',window.selectedPlot==p.dataset.plot);p.classList.toggle('claimed',s.home==p.dataset.plot)});document.querySelectorAll('.worlds button').forEach(b=>b.classList.toggle('selected',b.dataset.world===s.world))}function setup(){let wc=$('worldChoices');wc.innerHTML=Object.entries(worlds).map(([k,w])=>'<button class="worldChoice" data-world="'+k+'">'+w.emoji+' <b>'+w.name+'</b><small>'+w.desc+'</small></button>').join('');$('worlds').innerHTML=Object.entries(worlds).map(([k,w])=>'<button data-world="'+k+'">'+w.emoji+' '+w.name.replace('NOMAD ','')+'</button>').join('');document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>changeWorld(b.dataset.world));document.querySelectorAll('.plot').forEach(p=>p.onclick=e=>{e.stopPropagation();window.selectedPlot=p.dataset.plot;msg('🏡 Terrain sélectionné. Il est libre : installez-vous ici si vous le souhaitez.');render()});$('claim').onclick=()=>{if(!window.selectedPlot)return;s.home=window.selectedPlot;s.money-=250;s.mood='Heureux';msg('🎉 Bienvenue chez vous ! Votre habitat se greffe à la ville NOMAD. La communauté était déjà là : vous venez simplement d’en devenir un membre.');save();render()};$('scene').onclick=e=>{if(e.target.closest('.plot'))return;let r=$('scene').getBoundingClientRect();s.x=Math.max(5,Math.min(92,(e.clientX-r.left)/r.width*100));s.y=Math.max(8,Math.min(88,(e.clientY-r.top)/r.height*100));s.time=(s.time+.25)%24;msg('🚶 Vous vous déplacez dans '+worlds[s.world].name+'. Votre humanoïde vous suit.');save();render()};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$('mapBtn').onclick=()=>{$('worldModal').classList.remove('hidden')};$('closeModal').onclick=()=>{$('worldModal').classList.add('hidden')};$('reset').onclick=()=>{localStorage.removeItem('nomadSims');location.reload()};render()}function changeWorld(w){s.world=w;s.home=null;window.selectedPlot=null;s.x=48;s.y=58;s.time=(s.time+1)%24;msg(worlds[w].emoji+' Vous arrivez dans '+worlds[w].city+'. La ville existe déjà : explorez-la avant de choisir votre emplacement.');$('worldModal').classList.add('hidden');save();render()}function action(a){let t={work:['🔧 Vous avez rejoint l’atelier de la ville. +80 NOMAD.','+80'],market:['🛒 Vous faites vos courses au marché local. -35 NOMAD.','-35'],meet:['👋 Vous rencontrez un voisin. La ville devient un peu plus familière.','0'],explore:['🧭 Vous explorez un nouveau quartier. Vous découvrez un emplacement intéressant.','0']}[a];if(a==='work')s.money+=80;if(a==='market')s.money=Math.max(0,s.money-35);s.time=(s.time+1)%24;s.mood=a==='meet'?'Sociable':s.mood;msg(t[0]);save();render()}setup();